<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute,useRouter} from 'vue-router';
import {EditorModel,analyzeToolboxRelease,applySkillTemplate,blankResource,isToolboxResource,kindLabels,normalizeMedia,errorMessage,toolboxCategories} from '../api';
import {login} from '../../../lib/session';
import AdminNav from '../components/AdminNav.vue';
import ContentState from '../components/ContentState.vue';
import DateFields from '../components/DateFields.vue';
import ResourceFields from '../components/ResourceFields.vue';
import MediaManager from '../components/MediaManager.vue';
import ToolboxFields from '../components/ToolboxFields.vue';
const route=useRoute(),router=useRouter();const model=ref(reactive(new EditorModel()));const confirmation=ref('');const relogin=ref(false),username=ref(''),password=ref('');
const toolboxWarningAccepted=ref(false);
const id=computed(()=>typeof route.params.id==='string'?route.params.id:'');
let replacing=false;
function startToolboxDraft(){const m=model.value;if(route.query.mode!=='toolbox'||id.value)return;m.kind='resource';m.form.category=toolboxCategories[0];m.form.resource=blankResource();applySkillTemplate(m.form);}
watch(id,async value=>{confirmation.value='';toolboxWarningAccepted.value=false;if(value&&model.value.saved?.id===value)return;model.value=reactive(new EditorModel());if(value)await model.value.load(value);else startToolboxDraft();},{immediate:true});
watch(()=>model.value.form.resource?.mode,mode=>{if(mode==='external')model.value.form.media=normalizeMedia(model.value.form.media.filter(l=>l.role!=='resourceFile'));});
function kindChange(){const m=model.value;toolboxWarningAccepted.value=false;m.form.transcription=null;m.form.reflection=null;m.form.resource=m.kind==='resource'?blankResource():null;m.form.game=m.kind==='game'?{launchUrl:'',usageInstructions:''}:null;if(m.kind==='resource'&&route.query.mode==='toolbox'){m.form.category=toolboxCategories[0];applySkillTemplate(m.form);}}
async function syncRoute(){if(!id.value&&model.value.saved){replacing=true;try{await router.replace(`/admin/contents/${model.value.saved.id}/edit`);}finally{replacing=false;}}}
async function save(){await model.value.save();await syncRoute();}
async function retry(){await model.value.retry();await syncRoute();}
function guardPublicToolboxPublish(){const saved=model.value.saved;if(!saved||saved.visibility!=='public'||!isToolboxResource(saved))return true;const scan=analyzeToolboxRelease(saved);if(scan.blockers.length){model.value.error=`AI 工具箱公开发布被阻止：${scan.blockers.join('；')}`;return false;}if(scan.warnings.length&&!toolboxWarningAccepted.value){model.value.error='AI 工具箱公开发布需要先勾选 WARNING 确认。';return false;}return true;}
function requestPublish(){model.value.error='';if(guardPublicToolboxPublish())confirmation.value='publish';}
async function confirmAction(){const action=confirmation.value;confirmation.value='';if(action==='publish'){if(!guardPublicToolboxPublish())return;await model.value.action('publish');}else if(action==='private')await model.value.action('visibility','private');else if(action==='withdraw')await model.value.action('withdraw');else if(action==='delete')await model.value.remove();else if(action==='reload'&&id.value)await model.value.load(id.value);}
function canLeave(){if(replacing)return true;if(model.value.busy){model.value.error='操作进行中，请等待完成后离开。';return false;}return !(model.value.dirty||model.value.pending)||window.confirm('当前有未保存修改或未核实操作。离开会丢失本页编辑和重试信息，确定离开？');}
onBeforeRouteLeave(canLeave);onBeforeRouteUpdate(to=>to.params.id===model.value.saved?.id||canLeave());
function beforeUnload(event:BeforeUnloadEvent){if(model.value.dirty||model.value.busy||model.value.pending){event.preventDefault();event.returnValue='';}}
window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));
async function signIn(){model.value.busy=true;model.value.error='';try{await login(username.value,password.value);password.value='';relogin.value=false;model.value.notice='已重新登录，编辑内容仍保留，请重试原操作';}catch(e){model.value.error=errorMessage(e);}finally{model.value.busy=false;}}
const actionDisabled=computed(()=>model.value.busy||model.value.dirty||!!model.value.pending||!!model.value.saved?.deletedAt);
</script>
<template><AdminNav/><span class="eyebrow">站主管理 · {{model.isDemo?'合成样本':'内容整理'}}</span><h1>{{id?'整理这份记录':'新建一份记录'}}</h1><ContentState :content="model.saved" :dirty="model.dirty" :busy="model.busy" :uncertain="!!model.pending"/><p v-if="model.error" role="alert" class="error">{{model.error}}</p><p v-if="model.notice" role="status" class="notice">{{model.notice}}</p><div v-if="model.pending" class="notice"><p>“{{model.pending.label}}”的结果尚未核实。保留了原始请求；请重试核实后再编辑。</p><button :disabled="model.busy" @click="retry">重试原操作</button></div><div class="support"><button class="quiet" :disabled="model.busy" @click="relogin=!relogin">在本页重新登录，保留编辑</button><button v-if="id" class="quiet" :disabled="model.busy||!!model.pending" @click="confirmation='reload'">重新读取服务器版本</button></div><form v-if="relogin" class="card reauth" @submit.prevent="signIn"><label>重新登录用户名<input v-model="username" autocomplete="username" required></label><label>重新登录密码<input v-model="password" type="password" autocomplete="current-password" required></label><button :disabled="model.busy">确认登录</button></form><p v-if="id&&!model.saved">{{model.busy?'正在读取记录…':'未取得内容，请重试读取；不会用空表单覆盖服务器记录。'}}</p><template v-else><p v-if="model.saved?.status==='published'" class="notice">已发布内容需要先撤回才能修改正文或上传文件。可以立即改为私密，停止后续访客访问。</p><p v-if="model.saved?.deletedAt" class="notice">此记录已软删除，仅供查看；归档原件仍保留。</p><form class="card" @submit.prevent="save"><fieldset :disabled="model.locked"><div class="columns"><label>内容类型<select v-model="model.kind" :disabled="!!model.saved" @change="kindChange"><option v-for="(label,key) in kindLabels" :key="key" :value="key">{{label}}</option></select></label><label v-if="!model.saved" class="check"><input v-model="model.isDemo" type="checkbox">这是合成测试样本</label></div><label>标题<input v-model="model.form.title" maxlength="120" required placeholder="给这份记录一个名字"></label><label>摘要（可选）<textarea v-model="model.form.summary" maxlength="500" rows="2"/></label><div class="columns"><label v-if="model.kind!=='resource'">基本分类（可选）<input v-model="model.form.category" maxlength="40"></label><label class="check"><input v-model="model.form.featured" type="checkbox">设为精选</label></div><DateFields v-model="model.form.recordDate"/><label>正文 / Markdown（可选）<textarea v-model="model.form.bodyText" maxlength="100000" rows="8"/></label><template v-if="model.kind==='diary'"><label>日记整理文字（可选）<textarea v-model="model.form.transcription" maxlength="100000" rows="6"/></label><label>现在的文字旁白（可选）<textarea v-model="model.form.reflection" maxlength="100000" rows="4"/></label></template><template v-if="model.kind==='resource'"><ToolboxFields v-model="model.form" v-model:warning-accepted="toolboxWarningAccepted" :disabled="model.locked"/><ResourceFields v-if="model.form.resource" v-model="model.form.resource"/><button v-else type="button" @click="model.form.resource=blankResource()">填写资源信息</button></template><template v-if="model.kind==='game'"><template v-if="model.form.game"><label>已有作品网址<input v-model="model.form.game.launchUrl" maxlength="2048" placeholder="https://…"></label><label>作品使用说明<textarea v-model="model.form.game.usageInstructions" maxlength="2000"/></label></template><button v-else type="button" @click="model.form.game={launchUrl:'',usageInstructions:''}">填写作品入口</button></template><label>下次发布的可见性<select v-model="model.form.visibility" :disabled="!model.saved"><option value="private">私密 · 仅站主可见</option><option value="public">公开 · 明确发布后访客可见</option></select></label><p v-if="!model.saved" class="muted">首次保存固定为私密草稿，之后可选择公开并再次保存。</p></fieldset><MediaManager :key="model.saved?.id||'new'" :model="model"/><div class="actions"><button :disabled="model.locked">{{model.busy?'处理中…':model.saved?'保存修改':'保存私密草稿'}}</button><RouterLink v-if="model.saved&&!model.busy&&!model.pending&&!model.dirty" :to="`/admin/contents/${model.saved.id}/preview`">预览已保存内容</RouterLink><span v-else-if="model.saved" class="muted">保存成功后可预览</span></div></form><section v-if="model.saved&&!model.saved.deletedAt" class="card publication"><h2>由你决定谁能看</h2><p>上传或保存都不会自动发布。已被访客保存的公开副本无法追回。</p><div class="actions"><button v-if="model.saved.status!=='published'" :disabled="actionDisabled" @click="requestPublish">发布{{model.saved.visibility==='public'?'为公开内容':'为私密内容'}}</button><button v-if="model.saved.visibility==='public'" :disabled="actionDisabled" @click="confirmation='private'">改为私密</button><button v-if="model.saved.status==='published'" :disabled="actionDisabled" @click="confirmation='withdraw'">撤回发布</button><button v-else class="quiet danger" :disabled="actionDisabled" @click="confirmation='delete'">软删除记录</button></div></section></template><section v-if="confirmation" class="card confirm" role="alertdialog" aria-modal="false" aria-labelledby="confirm-title"><h2 id="confirm-title">请确认本次操作</h2><p v-if="confirmation==='publish'">将发布当前已保存版本，可见性：{{model.saved?.visibility==='public'?'公开，所有访客可见':'私密，仅站主可见'}}。</p><p v-else-if="confirmation==='private'">改为私密后，后续访客请求无法再取得内容及关联附件。</p><p v-else-if="confirmation==='withdraw'">撤回发布后，仅站主可见，正文及原件继续保留。</p><p v-else-if="confirmation==='delete'">只软删除此记录，原件继续保留并纳入完整导出；首版没有恢复界面。</p><p v-else>重新读取会放弃本页未保存内容。请先复制需要保留的文字，再继续。</p><div class="actions"><button :disabled="model.busy" @click="confirmAction">确认{{confirmation==='publish'?'发布':'操作'}}</button><button class="quiet" @click="confirmation=''">取消</button></div></section></template>
<style scoped>fieldset{border:0;padding:0;min-width:0}label{display:grid;gap:6px;margin:16px 0}textarea{width:100%;resize:vertical}.columns,.actions,.support{display:flex;flex-wrap:wrap;gap:16px;align-items:center}.columns>label{flex:1;min-width:140px}.check{display:flex;align-items:center}.publication,.confirm,.reauth{margin-top:24px}.confirm{border:2px solid var(--accent)}.danger{color:var(--danger)}.actions a{color:var(--accent);font-weight:600}.support{margin-bottom:20px}.reauth{margin-bottom:24px}.error{white-space:pre-wrap;overflow-wrap:anywhere}</style>
